CREATE OR REPLACE FUNCTION public.payroll_lock_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE t uuid;y integer;m integer;BEGIN t:=COALESCE(NEW.tenant_id,OLD.tenant_id);y:=COALESCE(NEW.year,OLD.year);m:=COALESCE(NEW.month,OLD.month);PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.employee_id,NEW.year,NEW.month) IS DISTINCT FROM (OLD.tenant_id,OLD.employee_id,OLD.year,OLD.month) AND EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=OLD.tenant_id AND year=OLD.year AND month=OLD.month AND status='approved') THEN RAISE EXCEPTION 'Approved payroll is locked';END IF;IF EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status='approved') THEN IF TG_OP<>'UPDATE' OR (to_jsonb(NEW)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) THEN RAISE EXCEPTION 'Approved payroll is locked; financial corrections require review';END IF;END IF;
IF current_user IN ('authenticated','anon') AND (TG_OP<>'UPDATE' OR (to_jsonb(NEW)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount'])) THEN RAISE EXCEPTION 'Use confirmed payroll changes';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE FUNCTION public.payroll_approve(t uuid,y integer,m integer,rev integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE period public.hr_payroll_months;rows jsonb;row jsonb;s jsonb;existing uuid;entry uuid;salary uuid;mpf uuid;salary_exp uuid;mpf_exp uuid;deductions uuid;r record;n integer:=0;line_no integer:=0;BEGIN
IF NOT public.payroll_manager(t,auth.uid()) OR NOT public.people_owner(t,auth.uid()) THEN RAISE EXCEPTION 'Owner approval required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));SELECT * INTO period FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m FOR UPDATE;IF period.id IS NULL OR period.revision<>rev THEN RAISE EXCEPTION 'Payroll changed; reload before approval';END IF;IF period.status='approved' THEN RETURN jsonb_build_object('already_approved',true);END IF;
rows:=public.payroll_preview(t,y,m);IF jsonb_array_length(rows)=0 THEN RAISE EXCEPTION 'No payroll to approve';END IF;
FOR row IN SELECT value FROM jsonb_array_elements(rows) LOOP
IF row->>'id' IS NULL OR jsonb_array_length(row->'preparation'->'missing')>0 THEN RAISE EXCEPTION 'Payroll still has missing inputs: %',row->>'name';END IF;s:=public.people_effective_settings(t,NULLIF(row->>'venue_id','')::uuid);IF s->>'approvals'='strict' AND period.prepared_by=auth.uid() THEN RAISE EXCEPTION 'Strict approval needs a different owner';END IF;END LOOP;
PERFORM 1 FROM public.hr_payroll WHERE tenant_id=t AND year=y AND month=m FOR UPDATE;
SELECT count(DISTINCT accrual_journal_entry_id),min(accrual_journal_entry_id::text)::uuid INTO n,existing FROM public.hr_payroll WHERE tenant_id=t AND year=y AND month=m;
IF n>1 OR existing IS NOT NULL AND EXISTS(SELECT 1 FROM public.hr_payroll WHERE tenant_id=t AND year=y AND month=m AND accrual_journal_entry_id IS NULL) THEN RAISE EXCEPTION 'Existing accrual is incomplete; Finance review required';END IF;
IF existing IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.journal_entries WHERE id=existing AND tenant_id=t AND status='posted') THEN RAISE EXCEPTION 'Existing accrual needs Finance review';END IF;entry:=existing;
ELSE
SELECT account_id INTO salary FROM public.account_mapping_rules WHERE tenant_id=t AND rule_type='salary_payable' AND match_key='' LIMIT 1;IF salary IS NULL THEN SELECT id INTO salary FROM public.chart_of_accounts WHERE tenant_id=t AND code='2040' LIMIT 1;END IF;
SELECT account_id INTO mpf FROM public.account_mapping_rules WHERE tenant_id=t AND rule_type='mpf_payable' AND match_key='' LIMIT 1;IF mpf IS NULL THEN SELECT id INTO mpf FROM public.chart_of_accounts WHERE tenant_id=t AND code='2030' LIMIT 1;END IF;
IF salary IS NULL OR mpf IS NULL THEN RAISE EXCEPTION 'Salary and MPF payable mappings are missing';END IF;
IF EXISTS(SELECT 1 FROM public.journal_entries WHERE tenant_id=t AND source_type='payroll_accrual' AND source_id=y||'-'||lpad(m::text,2,'0') AND status<>'void') THEN RAISE EXCEPTION 'An unlinked accrual exists; Finance review required';END IF;
INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,status,created_by) VALUES(t,(make_date(y,m,1)+interval '1 month -1 day')::date,'Payroll accrual — '||to_char(make_date(y,m,1),'FMMonth YYYY'),'payroll_accrual',y||'-'||lpad(m::text,2,'0'),'draft',auth.uid()) RETURNING id INTO entry;
FOR r IN SELECT COALESCE(v.name,'Unassigned') venue,sum(p.gross_salary) gross,sum(p.net_salary) net,sum(p.mpf_employee) ee,sum(p.mpf_employer) er,sum(p.other_deductions) other FROM public.hr_payroll p JOIN public.hr_employees e ON e.id=p.employee_id AND e.tenant_id=t LEFT JOIN public.venues v ON v.id=COALESCE(NULLIF(public.people_terms_at(t,e.id,make_date(y,m,1))->>'venue_id','')::uuid,e.venue_id) AND v.tenant_id=t WHERE p.tenant_id=t AND p.year=y AND p.month=m GROUP BY v.name LOOP
salary_exp:=NULL;mpf_exp:=NULL;SELECT account_id INTO salary_exp FROM public.account_mapping_rules WHERE tenant_id=t AND rule_type IN ('payroll_salary_expense','salary_expense') AND match_key IN (r.venue,'') ORDER BY (match_key=r.venue) DESC LIMIT 1;IF salary_exp IS NULL THEN SELECT id INTO salary_exp FROM public.chart_of_accounts WHERE tenant_id=t AND code='6010' LIMIT 1;END IF;
SELECT account_id INTO mpf_exp FROM public.account_mapping_rules WHERE tenant_id=t AND rule_type IN ('payroll_mpf_expense','mpf_expense') AND match_key IN (r.venue,'') ORDER BY (match_key=r.venue) DESC LIMIT 1;IF mpf_exp IS NULL THEN SELECT id INTO mpf_exp FROM public.chart_of_accounts WHERE tenant_id=t AND code='6020' LIMIT 1;END IF;
IF salary_exp IS NULL OR mpf_exp IS NULL THEN RAISE EXCEPTION 'Salary and employer MPF expense mappings are missing';END IF;
IF r.gross<0 OR r.net<0 OR r.ee<0 OR r.er<0 THEN RAISE EXCEPTION 'Negative pay needs Finance review';END IF;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,line_no,memo) VALUES(t,entry,salary_exp,r.gross,0,r.venue,line_no+1,'Gross salary — '||r.venue),(t,entry,mpf_exp,r.er,0,r.venue,line_no+2,'MPF employer — '||r.venue),(t,entry,salary,0,r.net,r.venue,line_no+3,'Net salary payable — '||r.venue),(t,entry,mpf,0,r.ee+r.er,r.venue,line_no+4,'MPF payable — '||r.venue);line_no:=line_no+4;
IF r.other<>0 THEN SELECT id INTO deductions FROM public.chart_of_accounts WHERE tenant_id=t AND code='1900' LIMIT 1;IF deductions IS NULL THEN RAISE EXCEPTION 'Other deductions need the existing suspense mapping';END IF;line_no:=line_no+1;INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,line_no,memo) VALUES(t,entry,deductions,0,r.other,r.venue,line_no,'Other payroll deductions — review in Finance');END IF;
END LOOP;
IF abs((SELECT sum(debit-credit) FROM public.journal_lines WHERE entry_id=entry AND tenant_id=t))>0.01 THEN RAISE EXCEPTION 'Payroll accrual does not balance';END IF;
UPDATE public.journal_entries SET status='posted',posted_at=now() WHERE id=entry AND tenant_id=t;
UPDATE public.hr_payroll SET accrual_journal_entry_id=entry WHERE tenant_id=t AND year=y AND month=m;
END IF;
INSERT INTO public.hr_payslips(tenant_id,payroll_id,employee_id,snapshot,created_by) SELECT t,id,employee_id,to_jsonb(p),auth.uid() FROM public.hr_payroll p WHERE p.tenant_id=t AND p.year=y AND p.month=m ON CONFLICT(payroll_id) DO NOTHING;
UPDATE public.hr_payroll_months SET status='approved',approved_by=auth.uid(),approved_at=now(),revision=revision+1 WHERE id=period.id;
RETURN jsonb_build_object('approved',true,'journal_entry_id',entry,'people',jsonb_array_length(rows));END $$;
REVOKE ALL ON FUNCTION public.payroll_approve(uuid,integer,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_approve(uuid,integer,integer,integer) TO authenticated;